package claudecodeadapter

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"reflect"
	"runtime"
	"strings"
	"testing"
	"time"

	"github.com/hecatehq/acp-adapter-kit/acptest"
	"github.com/hecatehq/acp-adapter-kit/commandbridge"
	adapterprocess "github.com/hecatehq/acp-adapter-kit/process"
)

func TestDiscoverAvailableCommandsUsesBareControlInventory(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("shell-script fake command is Unix-only")
	}
	workdir := t.TempDir()
	extraDir := t.TempDir()
	metadataPath := filepath.Join(t.TempDir(), "metadata")
	stdinPath := filepath.Join(t.TempDir(), "stdin")
	response := "{\"type\":\"control_response\",\"response\":{\"request_id\":\"hecate-command-discovery\",\"subtype\":\"success\",\"response\":{\"commands\":[{\"name\":\"goal\",\"description\":\"Set a durable goal.\",\"argumentHint\":\"outcome\"},{\"name\":\"loop\",\"description\":\"Run a loop until complete.\",\"argumentHint\":\"[interval]\",\"aliases\":[\"proactive\"]},{\"name\":\"/workspace-skill\",\"description\":\"Use the workspace skill.\"}],\"account\":{\"email\":\"private@example.test\"},\"models\":[{\"id\":\"private-model\"}],\"agents\":[{\"name\":\"private-agent\"}]}}}"
	script := "#!/bin/sh\nset -eu\n" +
		"{\n" +
		"  printf 'cwd=%s\\n' \"$PWD\"\n" +
		"  printf 'args='\n" +
		"  printf '%s\\037' \"$@\"\n" +
		"  printf '\\n'\n" +
		"  printf 'unrelated=%s\\n' \"${HECATE_DISCOVERY_UNRELATED-}\"\n" +
		"} > " + shellQuote(metadataPath) + "\n" +
		"cat > " + shellQuote(stdinPath) + "\n" +
		"printf '%s\\n' " + shellQuote("{\"type\":\"system\",\"account\":{\"email\":\"private@example.test\"}}") + "\n" +
		"printf '%s\\n' " + shellQuote(response) + "\n"
	installDiscoveryFakeClaude(t, script)
	t.Setenv("HECATE_DISCOVERY_UNRELATED", "must-not-leak")

	commands, err := discoverAvailableCommands(context.Background(), commandbridge.CommandDiscoverySession{
		ID:                    "session-1",
		CWD:                   workdir,
		AdditionalDirectories: []string{extraDir},
	}, commandbridge.ProcessRunner{})
	if err != nil {
		t.Fatalf("discoverAvailableCommands: %v", err)
	}
	wantCommands := []commandbridge.AvailableCommand{
		{Name: "goal", Description: "Set a durable goal.", InputHint: "outcome"},
		{Name: "loop", Description: "Run a loop until complete.", InputHint: "[interval]"},
		{Name: "workspace-skill", Description: "Use the workspace skill."},
		{Name: "proactive", Description: "Alias for /loop: Run a loop until complete.", InputHint: "[interval]"},
	}
	if !reflect.DeepEqual(commands, wantCommands) {
		t.Fatalf("commands = %#v, want %#v", commands, wantCommands)
	}

	metadata, err := os.ReadFile(metadataPath)
	if err != nil {
		t.Fatalf("read metadata: %v", err)
	}
	canonicalWorkdir, err := filepath.EvalSymlinks(workdir)
	if err != nil {
		t.Fatalf("resolve workdir: %v", err)
	}
	metadataLines := strings.Split(strings.TrimSuffix(string(metadata), "\n"), "\n")
	if len(metadataLines) != 3 || metadataLines[0] != "cwd="+canonicalWorkdir || metadataLines[2] != "unrelated=" {
		t.Fatalf("discovery metadata = %q, want cwd and no unrelated environment", metadata)
	}
	args := strings.Split(strings.TrimSuffix(strings.TrimPrefix(metadataLines[1], "args="), "\x1f"), "\x1f")
	wantArgs := []string{
		"--print",
		"--bare",
		"--input-format", "stream-json",
		"--output-format", "stream-json",
		"--verbose",
		"--no-session-persistence",
		"--permission-mode", "dontAsk",
		"--strict-mcp-config",
	}
	if !reflect.DeepEqual(args, wantArgs) {
		t.Fatalf("discovery args = %#v, want %#v", args, wantArgs)
	}
	for _, forbidden := range []string{"--mcp-config", "--session-id", "--resume", "--add-dir"} {
		for _, arg := range args {
			if arg == forbidden {
				t.Fatalf("discovery args = %#v, must not include %q", args, forbidden)
			}
		}
	}

	stdin, err := os.ReadFile(stdinPath)
	if err != nil {
		t.Fatalf("read discovery stdin: %v", err)
	}
	var request map[string]any
	if err := json.Unmarshal(stdin, &request); err != nil {
		t.Fatalf("decode discovery control request: %v", err)
	}
	requestBody, _ := request["request"].(map[string]any)
	if request["type"] != "control_request" || request["request_id"] != claudeCommandDiscoveryRequestID ||
		requestBody["subtype"] != "initialize" || !reflect.DeepEqual(requestBody["systemPrompt"], []any{""}) {
		t.Fatalf("discovery control request = %#v, want no-prompt initialize", request)
	}
}

func TestDiscoverAvailableCommandsKeepsProviderOutputPrivateOnFailure(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("shell-script fake command is Unix-only")
	}
	installDiscoveryFakeClaude(t, "#!/bin/sh\nset -eu\ncat >/dev/null\nprintf '%s\\n' '{\"type\":\"control_response\",\"response\":{\"request_id\":\"another-request\",\"subtype\":\"success\",\"response\":{\"commands\":[]}}}'\nprintf '%s\\n' 'private-token-never-show' >&2\nexit 1\n")

	_, err := discoverAvailableCommands(context.Background(), commandbridge.CommandDiscoverySession{CWD: t.TempDir()}, commandbridge.ProcessRunner{})
	if err == nil {
		t.Fatal("discoverAvailableCommands error = nil, want missing matching response")
	}
	if strings.Contains(err.Error(), "private-token-never-show") || strings.Contains(err.Error(), "another-request") {
		t.Fatalf("discovery error = %q, must not expose provider output", err)
	}
}

func TestDiscoverAvailableCommandsRejectsMissingOrNullCommands(t *testing.T) {
	for _, name := range []string{"missing", "null"} {
		t.Run(name, func(t *testing.T) {
			commands := "{}"
			if name == "null" {
				commands = "{\"commands\":null}"
			}
			line := "{\"type\":\"control_response\",\"response\":{\"request_id\":\"hecate-command-discovery\",\"subtype\":\"success\",\"response\":" + commands + "}}"
			_, matched, err := parseClaudeCommandDiscoveryLine([]byte(line))
			if !matched || err == nil {
				t.Fatalf("parse result = matched:%v err:%v, want matching malformed response", matched, err)
			}
		})
	}

	commands, matched, err := parseClaudeCommandDiscoveryLine([]byte("{\"type\":\"control_response\",\"response\":{\"request_id\":\"hecate-command-discovery\",\"subtype\":\"success\",\"response\":{\"commands\":[]}}}"))
	if err != nil || !matched || commands == nil || len(commands) != 0 {
		t.Fatalf("explicit empty response = commands:%#v matched:%v err:%v, want authoritative empty snapshot", commands, matched, err)
	}
}

func TestDiscoverAvailableCommandsCancelsBoundedProbe(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("shell-script fake command is Unix-only")
	}
	installDiscoveryFakeClaude(t, "#!/bin/sh\nset -eu\ncat >/dev/null\nsleep 10\n")
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	_, err := discoverAvailableCommands(ctx, commandbridge.CommandDiscoverySession{CWD: t.TempDir()}, commandbridge.ProcessRunner{})
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("discoverAvailableCommands error = %v, want context deadline", err)
	}
}

func TestClaudeAvailableCommandsToACPPrioritizesCanonicalsAndBoundsProviderFields(t *testing.T) {
	got := claudeAvailableCommandsToACP([]claudeAvailableCommand{
		{Name: "goal", Description: "Goal", Aliases: []string{"loop", "objective"}},
		{Name: "loop", Description: "Canonical loop", Aliases: []string{"proactive"}},
	})
	want := []commandbridge.AvailableCommand{
		{Name: "goal", Description: "Goal"},
		{Name: "loop", Description: "Canonical loop"},
		{Name: "objective", Description: "Alias for /goal: Goal"},
		{Name: "proactive", Description: "Alias for /loop: Canonical loop"},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("commands = %#v, want canonical commands before aliases %#v", got, want)
	}

	source := make([]claudeAvailableCommand, claudeCommandDiscoveryMaxCommands)
	for index := range source {
		source[index] = claudeAvailableCommand{
			Name:         fmt.Sprintf("command-%03d", index),
			Description:  strings.Repeat("\x01", claudeCommandDiscoveryMaxDescriptionBytes*8),
			ArgumentHint: strings.Repeat("\x01", claudeCommandDiscoveryMaxHintBytes*8),
			Aliases:      []string{fmt.Sprintf("alias-%03d", index)},
		}
	}
	bounded := claudeAvailableCommandsToACP(source)
	var total int
	for _, command := range bounded {
		if len(command.Name) > claudeCommandDiscoveryMaxNameBytes ||
			len(command.Description) > claudeCommandDiscoveryMaxDescriptionBytes ||
			len(command.InputHint) > claudeCommandDiscoveryMaxHintBytes {
			t.Fatalf("command field exceeds bound: %#v", command)
		}
		total += claudeAvailableCommandWireSize(command)
	}
	if len(bounded) > claudeCommandDiscoveryMaxCommands || total > claudeCommandDiscoveryMaxCatalogBytes {
		t.Fatalf("bounded catalog count=%d bytes=%d, want <=%d and <=%d", len(bounded), total, claudeCommandDiscoveryMaxCommands, claudeCommandDiscoveryMaxCatalogBytes)
	}
}

func TestClaudeAvailableCommandWireSizeMatchesACPCommandShape(t *testing.T) {
	for _, test := range []struct {
		name    string
		command commandbridge.AvailableCommand
		wire    string
	}{
		{
			name:    "hint and empty description",
			command: commandbridge.AvailableCommand{Name: " goal ", InputHint: " outcome "},
			wire:    `{"name":"goal","description":"","input":{"hint":"outcome"}}`,
		},
		{
			name:    "description without hint",
			command: commandbridge.AvailableCommand{Name: "plan", Description: " Create a plan "},
			wire:    `{"name":"plan","description":"Create a plan"}`,
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			if got, want := claudeAvailableCommandWireSize(test.command), len(test.wire)+1; got != want {
				t.Fatalf("wire size = %d, want %d for %s", got, want, test.wire)
			}
		})
	}
}

func TestClaudeCommandDiscoveryCountingReaderBoundsWholeStream(t *testing.T) {
	limited := &claudeCommandDiscoveryCountingReader{
		Reader: io.LimitReader(strings.NewReader(strings.Repeat("x", claudeCommandDiscoveryMaxTotalBytes*2)), claudeCommandDiscoveryMaxTotalBytes),
	}
	if _, err := io.ReadAll(limited); err != nil {
		t.Fatalf("read limited stream: %v", err)
	}
	if limited.BytesRead != claudeCommandDiscoveryMaxTotalBytes {
		t.Fatalf("read bytes = %d, want total cap %d", limited.BytesRead, claudeCommandDiscoveryMaxTotalBytes)
	}
}

func TestNewServerPublishesDiscoveredCommands(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("shell-script fake command is Unix-only")
	}
	installDiscoveryFakeClaude(t, "#!/bin/sh\nset -eu\ncat >/dev/null\nprintf '%s\\n' '{\"type\":\"control_response\",\"response\":{\"request_id\":\"hecate-command-discovery\",\"subtype\":\"success\",\"response\":{\"commands\":[{\"name\":\"goal\",\"description\":\"Set a goal.\",\"argumentHint\":\"outcome\"},{\"name\":\"loop\",\"aliases\":[\"proactive\"]}]}}}'\n")

	updates := make(chan json.RawMessage, 1)
	client := acptest.NewLiveClient(t, NewServerWithRunner("test", discoveryTestRunner{}), acptest.WithLiveResponseHandler(func(_ *acptest.LiveClient, response acptest.Response) {
		if response.Method != "session/update" {
			return
		}
		var payload map[string]any
		response.ParamsInto(t, &payload)
		update, _ := payload["update"].(map[string]any)
		if update["sessionUpdate"] != "available_commands_update" {
			return
		}
		select {
		case updates <- append(json.RawMessage(nil), response.Params...):
		default:
		}
	}))

	responses := client.Request("new", "session/new", map[string]any{"cwd": t.TempDir()}, time.Second)
	var sessionID string
	for _, response := range responses {
		if response.Method != "" || response.Error != nil {
			continue
		}
		var result map[string]any
		response.ResultInto(t, &result)
		sessionID, _ = result["sessionId"].(string)
	}
	if sessionID == "" {
		t.Fatalf("session/new responses = %#v, want session result", responses)
	}
	raw := waitForDiscoveredCommandUpdate(t, client, updates)
	var catalog struct {
		Update struct {
			AvailableCommands []map[string]json.RawMessage `json:"availableCommands"`
		} `json:"update"`
	}
	if err := json.Unmarshal(raw, &catalog); err != nil {
		t.Fatalf("decode discovered command notification: %v", err)
	}
	got := make([]string, 0, len(catalog.Update.AvailableCommands))
	for _, command := range catalog.Update.AvailableCommands {
		var name string
		if err := json.Unmarshal(command["name"], &name); err != nil {
			t.Fatalf("decode discovered command name: %v", err)
		}
		got = append(got, name)
	}
	if want := []string{"goal", "loop", "proactive"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("discovered command names = %#v, want %#v", got, want)
	}
	if got := string(catalog.Update.AvailableCommands[0]["input"]); got != `{"hint":"outcome"}` {
		t.Fatalf("discovered command input wire = %s, want flat hint", got)
	}
	if got := string(catalog.Update.AvailableCommands[1]["description"]); got != `""` {
		t.Fatalf("empty discovered command description wire = %s, want required empty string", got)
	}
}

func TestNewServerKeepsSessionUsableWhenCommandDiscoveryFails(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("shell-script fake command is Unix-only")
	}
	installDiscoveryFakeClaude(t, "#!/bin/sh\nset -eu\ncat >/dev/null\nexit 1\n")
	client := acptest.NewLiveClient(t, NewServerWithRunner("test", discoveryTestRunner{}))

	responses := client.Request("new", "session/new", map[string]any{"cwd": t.TempDir()}, time.Second)
	for _, response := range responses {
		if response.Method != "" || response.Error != nil {
			continue
		}
		var result map[string]any
		response.ResultInto(t, &result)
		if sessionID, _ := result["sessionId"].(string); sessionID != "" {
			return
		}
	}
	t.Fatalf("session/new responses = %#v, want usable session despite failed discovery", responses)
}

type discoveryTestRunner struct{}

func (discoveryTestRunner) Run(ctx context.Context, spec adapterprocess.Spec) (adapterprocess.Result, error) {
	return adapterprocess.Run(ctx, spec)
}

func (discoveryTestRunner) RunStream(ctx context.Context, spec adapterprocess.Spec, onStdout func([]byte) error) (adapterprocess.Result, error) {
	return adapterprocess.RunStream(ctx, spec, onStdout)
}

func (discoveryTestRunner) Start(ctx context.Context, spec adapterprocess.StartSpec) (*adapterprocess.Child, error) {
	return adapterprocess.Start(ctx, spec)
}

func installDiscoveryFakeClaude(t testing.TB, script string) {
	t.Helper()
	dir := t.TempDir()
	path := filepath.Join(dir, "claude")
	if err := os.WriteFile(path, []byte(script), 0o755); err != nil {
		t.Fatalf("write fake Claude command: %v", err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
}

func shellQuote(value string) string {
	return "'" + strings.ReplaceAll(value, "'", "'\"'\"'") + "'"
}

func waitForDiscoveredCommandUpdate(t testing.TB, client *acptest.LiveClient, updates <-chan json.RawMessage) json.RawMessage {
	t.Helper()
	deadline := time.Now().Add(time.Second)
	for {
		select {
		case update := <-updates:
			return update
		default:
		}
		remaining := time.Until(deadline)
		if remaining <= 0 {
			t.Fatal("timed out waiting for discovered command update")
		}
		if remaining > 10*time.Millisecond {
			remaining = 10 * time.Millisecond
		}
		client.AssertNoLateResponse("available-command-wait", remaining)
	}
}

package claudecodeadapter

import (
	"errors"
	"testing"
)

type failingEntropyReader struct{}

func (failingEntropyReader) Read([]byte) (int, error) {
	return 0, errors.New("entropy unavailable")
}

func TestNewClaudeSessionIDFailsClosedWithoutEntropy(t *testing.T) {
	if id := newClaudeSessionIDFrom(failingEntropyReader{}); id != "" {
		t.Fatalf("session id = %q, want empty id so the bridge rejects creation", id)
	}
}

//go:build real_cli

package claudecodeadapter_test

import (
	"crypto/rand"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/hecatehq/acp-adapter-kit/acptest"
	"github.com/hecatehq/claude-code-acp-adapter/claudecodeadapter"
)

const realCLISmokeEnv = "ACP_ADAPTER_REAL_CLI_SMOKE"

func TestRealClaudeCodeCLISmoke(t *testing.T) {
	if os.Getenv(realCLISmokeEnv) != "1" {
		t.Skipf("set %s=1 to run the authenticated real Claude Code CLI smoke", realCLISmokeEnv)
	}
	if _, err := exec.LookPath("claude"); err != nil {
		t.Fatalf("claude CLI not found in PATH: %v", err)
	}

	commandCatalogs := make(chan realCLICommandCatalog, 16)
	client := acptest.NewLiveClient(t, claudecodeadapter.NewServer("real-cli-smoke"), acptest.WithLiveResponseHandler(func(client *acptest.LiveClient, response acptest.Response) {
		client.AutoAllowPermission(response)
		if catalog, ok := realCLICommandCatalogFromResponse(response); ok {
			select {
			case commandCatalogs <- catalog:
			default:
			}
		}
	}))
	client.Request("initialize", "initialize", map[string]any{}, 4*time.Minute)

	session := newRealCLISession(t, client, t.TempDir())
	assertRealCLICommandCatalog(t, client, commandCatalogs, session.SessionID)
	assertRealCLISessionLifecycle(t, client, session.SessionID, session.CWD)

	responses := client.PromptText("prompt-basic", session.SessionID, "Reply briefly with one sentence confirming the Claude Code ACP adapter real CLI smoke. Do not inspect files or run commands.", 4*time.Minute)
	assertRealCLIPromptCompleted(t, responses, "Claude Code")
	assertRealCLIMissingSessionClassification(t, client)

	setRealCLIConfigOption(t, client, session.SessionID, "permission_mode", "bypassPermissions")
	toolFile := filepath.Join(session.CWD, "acp-real-cli-tool.txt")
	toolResponses := client.PromptText("prompt-tool", session.SessionID, "Use a local shell command or file edit to create acp-real-cli-tool.txt in the current workspace containing exactly claude-code-acp-real-cli-tool. Then reply with one sentence starting with DONE.", 4*time.Minute)
	assertRealCLIPromptCompleted(t, toolResponses, "Claude Code")
	assertRealCLIToolFlow(t, toolResponses, "Claude Code")
	raw, err := os.ReadFile(toolFile)
	if err != nil {
		t.Fatalf("read tool-created file: %v", err)
	}
	if strings.TrimSpace(string(raw)) != "claude-code-acp-real-cli-tool" {
		t.Fatalf("tool-created file = %q, want claude-code-acp-real-cli-tool", string(raw))
	}

	mcpDir := t.TempDir()
	mcpRecord := filepath.Join(mcpDir, "mcp-record.txt")
	mcpSession := newRealCLISessionWithMCP(t, client, t.TempDir(), acptest.BuildMCPStdioEchoServer(t, mcpDir), mcpRecord)
	setRealCLIConfigOption(t, client, mcpSession.SessionID, "permission_mode", "bypassPermissions")
	mcpResponses := client.PromptText("prompt-mcp", mcpSession.SessionID, "Use the MCP tool named echo from the MCP server named hecatesmoke exactly once with text claude-code-mcp-smoke. Then reply with one sentence starting with DONE.", 4*time.Minute)
	assertRealCLIPromptCompleted(t, mcpResponses, "Claude Code")
	assertRealCLIMCPFlow(t, mcpResponses, "Claude Code")
	assertRealCLIMCPRecord(t, mcpRecord, "claude-code-mcp-smoke")

	cancelSession := newRealCLISession(t, client, t.TempDir())
	setRealCLIConfigOption(t, client, cancelSession.SessionID, "permission_mode", "bypassPermissions")
	cancelResponses := client.PromptTextAndCancel("prompt-cancel", cancelSession.SessionID, "Run a local shell command that sleeps for 30 seconds, then reply with the word done.", 4*time.Second, 4*time.Minute)
	assertRealCLIPromptCancelled(t, cancelResponses, "Claude Code")
	client.AssertNoLateResponse("prompt-cancel", time.Second)
}

func assertRealCLIMissingSessionClassification(t testing.TB, client *acptest.LiveClient) {
	t.Helper()
	missingID := randomRealCLIUUID(t)
	loadResponses := client.Request("session-load-missing", "session/load", map[string]any{
		"sessionId": missingID,
		"cwd":       t.TempDir(),
	}, 4*time.Minute)
	if len(loadResponses) == 0 {
		t.Fatal("session/load for missing native conversation returned no responses")
	}
	var loadResult map[string]any
	loadResponses[len(loadResponses)-1].ResultInto(t, &loadResult)

	responses := client.PromptText("prompt-missing-native", missingID, "Reply with the word unreachable.", 4*time.Minute)
	assertMissingClaudeSessionLifecycle(t, responses, missingID)
}

func randomRealCLIUUID(t testing.TB) string {
	t.Helper()
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		t.Fatalf("generate missing native session UUID: %v", err)
	}
	value[6] = (value[6] & 0x0f) | 0x40
	value[8] = (value[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", value[0:4], value[4:6], value[6:8], value[8:10], value[10:16])
}

func assertRealCLIPromptCompleted(t testing.TB, responses []acptest.Response, provider string) {
	t.Helper()
	if len(responses) < 3 {
		t.Fatalf("%s prompt responses = %#v, want command start, assistant output, command finish, and prompt result", provider, responses)
	}

	var message strings.Builder
	for _, response := range responses {
		if response.Error != nil {
			t.Fatalf("%s prompt response error: %+v", provider, *response.Error)
		}
		if response.Method != "session/update" {
			continue
		}
		update := decodeSessionUpdate(t, response)
		if update.Update.SessionUpdate == "agent_message_chunk" {
			message.WriteString(decodeChunkText(t, update.Update.Content))
		}
	}
	if strings.TrimSpace(message.String()) == "" {
		t.Fatalf("%s prompt emitted no assistant message chunk: %#v", provider, responses)
	}

	var promptResult struct {
		StopReason string `json:"stopReason"`
	}
	responses[len(responses)-1].ResultInto(t, &promptResult)
	if promptResult.StopReason != "end_turn" {
		t.Fatalf("%s stop reason = %q, want end_turn", provider, promptResult.StopReason)
	}
}

type realCLISession struct {
	SessionID string
	CWD       string
}

type realCLICommandCatalog struct {
	SessionID string
}

func realCLICommandCatalogFromResponse(response acptest.Response) (realCLICommandCatalog, bool) {
	if response.Method != "session/update" {
		return realCLICommandCatalog{}, false
	}
	var payload struct {
		SessionID string `json:"sessionId"`
		Update    struct {
			SessionUpdate     string            `json:"sessionUpdate"`
			AvailableCommands []json.RawMessage `json:"availableCommands"`
		} `json:"update"`
	}
	if err := json.Unmarshal(response.Params, &payload); err != nil || payload.Update.SessionUpdate != "available_commands_update" || payload.Update.AvailableCommands == nil {
		return realCLICommandCatalog{}, false
	}
	return realCLICommandCatalog{SessionID: payload.SessionID}, true
}

func assertRealCLICommandCatalog(t testing.TB, client *acptest.LiveClient, catalogs <-chan realCLICommandCatalog, sessionID string) {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for {
		select {
		case catalog := <-catalogs:
			if catalog.SessionID != sessionID {
				continue
			}
			// ACP treats an explicit empty catalog as a valid replacement
			// snapshot. This live gate verifies delivery; the fake-CLI suite
			// separately covers names and aliases.
			return
		default:
		}
		remaining := time.Until(deadline)
		if remaining <= 0 {
			t.Fatalf("timed out waiting for real CLI command catalog for %q", sessionID)
		}
		if remaining > 50*time.Millisecond {
			remaining = 50 * time.Millisecond
		}
		client.AssertNoLateResponse("real-cli-command-catalog", remaining)
	}
}

