		t.Fatalf("created session = %#v, want id and three config options", created)
	}
	if created.ConfigOptions[0].ID != "model" || created.ConfigOptions[0].Category != "model" {
		t.Fatalf("model option = %#v, want model category", created.ConfigOptions[0])
	}
	if created.ConfigOptions[1].ID != "effort" || created.ConfigOptions[1].Category != "thought_level" {
		t.Fatalf("effort option = %#v, want thought_level category", created.ConfigOptions[1])
	}
	if created.ConfigOptions[2].ID != "permission_mode" || created.ConfigOptions[2].Category != "permission" || created.ConfigOptions[2].CurrentValue != "dontAsk" {
		t.Fatalf("permission option = %#v, want permission category with dontAsk default", created.ConfigOptions[2])
	}
	assertConfigOptionUpdate(t, responses[1], "model", "sonnet")
	var modelSet struct {
		ConfigOptions []struct {
			ID           string `json:"id"`
			CurrentValue string `json:"currentValue"`
		} `json:"configOptions"`
	}
	decodeAppResult(t, responses[2], &modelSet)
	if len(modelSet.ConfigOptions) != 3 || modelSet.ConfigOptions[0].CurrentValue != "sonnet" {
		t.Fatalf("model set result = %#v, want selected model", modelSet.ConfigOptions)
	}
	assertConfigOptionUpdate(t, responses[3], "effort", "high")
	assertConfigOptionUpdate(t, responses[5], "permission_mode", "plan")

	start := decodeAppUpdate(t, responses[7])
	if start.Update.SessionUpdate != "tool_call" ||
		start.Update.Status != "in_progress" ||
		start.Update.ToolCallID == "" {
		t.Fatalf("tool start = %#v, want running command", start)
	}
	update := decodeAppUpdate(t, responses[8])
	if update.Update.SessionUpdate != "agent_message_chunk" || decodeAppChunkText(t, update.Update.Content) != "claude answer" {
		t.Fatalf("assistant update = %#v, want claude answer", update)
	}
	finish := decodeAppUpdate(t, responses[9])
	if finish.Update.SessionUpdate != "tool_call_update" ||
		finish.Update.ToolCallID != start.Update.ToolCallID ||
		finish.Update.Status != "completed" {
		t.Fatalf("tool finish = %#v, want completed command", finish)
	}
	info := decodeAppUpdate(t, responses[10])
	if info.Update.SessionUpdate != "session_info_update" ||
		info.Update.Title != "hello claude" ||
		info.Update.UpdatedAt == "" {
		t.Fatalf("session info = %#v, want transcript metadata", info)
	}
	var prompt struct {
		StopReason string `json:"stopReason"`
	}
	decodeAppResult(t, responses[11], &prompt)
	if prompt.StopReason != "end_turn" {
		t.Fatalf("stop reason = %q, want end_turn", prompt.StopReason)
	}
}

func TestCommandBridgeGrantsPrivateResourceStageBeforeDelimitedPrompt(t *testing.T) {
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	workdir := t.TempDir()
	sourceDir := t.TempDir()
	sourcePath := filepath.Join(sourceDir, "input.txt")
	if err := os.WriteFile(sourcePath, []byte("private input"), 0o600); err != nil {
		t.Fatalf("write source file: %v", err)
	}
	uriPath := filepath.ToSlash(sourcePath)
	if !strings.HasPrefix(uriPath, "/") {
		uriPath = "/" + uriPath
	}
	sourceURI := (&url.URL{Scheme: "file", Path: uriPath}).String()
	requests := []map[string]any{
		{
			"jsonrpc": "2.0",
			"id":      1,
			"method":  "session/new",
			"params":  map[string]any{"cwd": workdir},
		},
		{
			"jsonrpc": "2.0",
			"id":      2,
			"method":  "session/prompt",
			"params": map[string]any{
				"sessionId": testClaudeSessionID,
				"prompt": []map[string]any{
					{"type": "text", "text": "read the attachment"},
					{"type": "resource_link", "uri": sourceURI, "name": "input.txt", "mimeType": "text/plain"},
				},
			},
		},
	}
	var input strings.Builder
	for _, request := range requests {
		encoded, err := json.Marshal(request)
		if err != nil {
			t.Fatalf("marshal request: %v", err)
		}
		input.Write(encoded)
		input.WriteByte('\n')
	}

	var stagedDir string
	spec := adapterSpec(strings.NewReader(input.String()), &stdout, &stderr)
	spec.Command.NewID = func() string { return testClaudeSessionID }
	spec.Command.Runner = commandbridge.RunnerFunc(func(_ context.Context, got adapterprocess.Spec) (adapterprocess.Result, error) {
		if got.Command != "claude" || got.Dir != workdir {
			t.Fatalf("process spec = %#v", got)
		}
		for index, arg := range got.Args {
			if arg == "--add-dir" && index+1 < len(got.Args) {
				stagedDir = got.Args[index+1]
			}
		}
		if stagedDir == "" || stagedDir == sourceDir {
			t.Fatalf("--add-dir = %q, want private prompt stage", stagedDir)
		}
		if len(got.Args) < 2 || got.Args[len(got.Args)-2] != "--" {
			t.Fatalf("args = %#v, want prompt delimiter", got.Args)
		}
		stagedPath := filepath.Join(stagedDir, "01-input.txt")
		prompt := got.Args[len(got.Args)-1]
		var renderedPath string
		for _, line := range strings.Split(prompt, "\n") {
			var manifest struct {
				Path string `json:"path"`
			}
			if err := json.Unmarshal([]byte(line), &manifest); err == nil && manifest.Path != "" {
				renderedPath = manifest.Path
				break
			}
		}
		encodedSourcePath, err := json.Marshal(sourcePath)
		if err != nil {
			t.Fatalf("marshal source path: %v", err)
		}
		if renderedPath != stagedPath || strings.Contains(prompt, sourcePath) ||
			strings.Contains(prompt, string(encodedSourcePath)) || strings.Contains(prompt, sourceURI) {
			t.Fatalf("prompt did not reference only the private staged path: rendered=%q want=%q", renderedPath, stagedPath)
		}
		data, err := os.ReadFile(stagedPath)
		if err != nil || string(data) != "private input" {
			t.Fatalf("read staged input: data=%q err=%v", data, err)
		}
		return adapterprocess.Result{Stdout: []byte("claude answer")}, nil
	})

	if code := adaptercli.Run(nil, spec); code != 0 {
		t.Fatalf("Run returned %d, want 0; stderr=%q stdout=%q", code, stderr.String(), stdout.String())
	}
	if stagedDir == "" {
		t.Fatal("runner did not observe a private prompt stage")
	}
	if _, err := os.Stat(stagedDir); !os.IsNotExist(err) {
		t.Fatalf("private prompt stage remains after turn: %v", err)
	}
}

