)

const (
	claudeCommandDiscoveryRequestID     = "hecate-command-discovery"
	claudeCommandDiscoveryMaxLines      = 64
	claudeCommandDiscoveryMaxBytes      = 1024 * 1024
	claudeCommandDiscoveryMaxTotalBytes = 2 * 1024 * 1024
	claudeCommandDiscoveryStderrMax     = 8 * 1024

	// Keep provider-controlled catalog data well below the ACP transport's
	// 1 MiB message cap, including JSON escaping and update-envelope overhead.
	claudeCommandDiscoveryMaxCommands         = 128
	claudeCommandDiscoveryMaxNameBytes        = 96
	claudeCommandDiscoveryMaxDescriptionBytes = 512
	claudeCommandDiscoveryMaxHintBytes        = 128
	claudeCommandDiscoveryMaxCatalogBytes     = 512 * 1024
	claudeCommandDiscoveryTimeout             = 3 * time.Second
)

// discoverAvailableCommands asks a short-lived, no-prompt Claude stream-json
// session for its current command inventory. The command response is the
// source of truth: no adapter-owned list filters, extends, or constrains it.
//
// Discovery deliberately omits prompt text, native session ids, MCP server
// configuration, and adapter/session metadata. --bare prevents automatic
// workspace hooks, plugin sync, keychain access, and CLAUDE.md discovery;
// --strict-mcp-config prevents configured MCP servers from starting. The
// resulting catalog comes from Claude CLI's documented bare/minimal startup
// boundary, rather than an unrestricted project/plugin startup inventory.
func discoverAvailableCommands(ctx context.Context, session commandbridge.CommandDiscoverySession, starter commandbridge.CommandStarter) ([]commandbridge.AvailableCommand, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if starter == nil {
		return nil, errors.New("Claude command discovery starter is required")
	}

	spec, err := claudeCommandDiscoverySpec(session)
	if err != nil {
		return nil, err
	}
	child, err := starter.Start(ctx, spec)
	if err != nil {
		return nil, fmt.Errorf("start Claude command discovery: %w", err)
	}
	defer func() {
		_ = child.Stdin.Close()
		_ = child.Kill()
		_ = child.Wait()
	}()

	request, err := json.Marshal(claudeCommandDiscoveryRequest{
		Type:      "control_request",
		RequestID: claudeCommandDiscoveryRequestID,
		Request: claudeControlRequest{
			Subtype:      "initialize",
			SystemPrompt: []string{""},
		},
	})
	if err != nil {
		return nil, fmt.Errorf("encode Claude command discovery request: %w", err)
	}
	request = append(request, '\n')
	if _, err := child.Stdin.Write(request); err != nil {
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		return nil, errors.New("send Claude command discovery request")
	}
	if err := child.Stdin.Close(); err != nil && ctx.Err() == nil {
		return nil, errors.New("close Claude command discovery input")
	}

	stdout := &claudeCommandDiscoveryCountingReader{
		Reader: io.LimitReader(child.Stdout, claudeCommandDiscoveryMaxTotalBytes),
	}
	scanner := bufio.NewScanner(stdout)
	scanner.Buffer(make([]byte, 0, 64*1024), claudeCommandDiscoveryMaxBytes)
	for lineCount := 0; scanner.Scan(); lineCount++ {
		if lineCount >= claudeCommandDiscoveryMaxLines {
			return nil, errors.New("Claude command discovery response exceeded line limit")
		}
		commands, matched, err := parseClaudeCommandDiscoveryLine(scanner.Bytes())
		if err != nil {
			return nil, err
		}
		if !matched {
			continue
		}
		return commands, nil
	}
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	if stdout.BytesRead >= claudeCommandDiscoveryMaxTotalBytes {
		return nil, errors.New("Claude command discovery response exceeded total size limit")
	}
	if err := scanner.Err(); err != nil {
		return nil, errors.New("read Claude command discovery response")
	}
	if err := child.Wait(); err != nil {
		return nil, errors.New("Claude command discovery exited before responding")
	}
	return nil, errors.New("Claude command discovery response is missing")
}

func claudeCommandDiscoverySpec(session commandbridge.CommandDiscoverySession) (adapterprocess.StartSpec, error) {
	cwd := strings.TrimSpace(session.CWD)
	if cwd == "" {
		return adapterprocess.StartSpec{}, errors.New("Claude command discovery cwd is required")
	}
	args := []string{
		"--print",
		"--bare",
		"--input-format", "stream-json",
		"--output-format", "stream-json",
		"--verbose",
		"--no-session-persistence",
		"--permission-mode", "dontAsk",
		"--strict-mcp-config",
	}
	return adapterprocess.StartSpec{
		Command:     "claude",
		Args:        args,
		Dir:         cwd,
		Env:         claudeProcessEnv(),
		StderrLimit: claudeCommandDiscoveryStderrMax,
	}, nil
}

type claudeCommandDiscoveryRequest struct {
	Type      string               `json:"type"`
	RequestID string               `json:"request_id"`
	Request   claudeControlRequest `json:"request"`
}

type claudeControlRequest struct {
	Subtype      string   `json:"subtype"`
	SystemPrompt []string `json:"systemPrompt"`
}

type claudeCommandDiscoveryEnvelope struct {
	Type     string          `json:"type"`
	Response json.RawMessage `json:"response"`
}

type claudeCommandDiscoveryResponse struct {
	RequestID string `json:"request_id"`
	Subtype   string `json:"subtype"`
	Response  struct {
		Commands *json.RawMessage `json:"commands"`
	} `json:"response"`
}

type claudeAvailableCommand struct {
	Name         string   `json:"name"`
	Description  string   `json:"description"`
	ArgumentHint string   `json:"argumentHint"`
	Aliases      []string `json:"aliases"`
}

func parseClaudeCommandDiscoveryLine(line []byte) ([]commandbridge.AvailableCommand, bool, error) {
	var envelope claudeCommandDiscoveryEnvelope
	if err := json.Unmarshal(line, &envelope); err != nil {
		// Claude's stream can contain non-control events before the response we
		// need. Ignore malformed or unrelated records without exposing their
		// contents through errors, logs, or ACP state.
		return nil, false, nil
	}
	if envelope.Type != "control_response" || len(envelope.Response) == 0 {
		return nil, false, nil
	}
	var response claudeCommandDiscoveryResponse
	if err := json.Unmarshal(envelope.Response, &response); err != nil {
		return nil, false, nil
	}
	if response.RequestID != claudeCommandDiscoveryRequestID {
		return nil, false, nil
	}
	if response.Subtype != "success" {
		return nil, true, errors.New("Claude command discovery was not successful")
	}
	if response.Response.Commands == nil {
		return nil, true, errors.New("Claude command discovery response omitted commands")
	}
	var commands []claudeAvailableCommand
	if err := json.Unmarshal(*response.Response.Commands, &commands); err != nil || commands == nil {
		return nil, true, errors.New("Claude command discovery response has invalid commands")
	}
	return claudeAvailableCommandsToACP(commands), true, nil
}

func claudeAvailableCommandsToACP(source []claudeAvailableCommand) []commandbridge.AvailableCommand {
	if len(source) == 0 {
		return []commandbridge.AvailableCommand{}
	}
	out := make([]commandbridge.AvailableCommand, 0, len(source))
	primary := make(map[string]struct{}, len(source))
	var catalogBytes int
	for _, command := range source {
		name := truncateClaudeCommandField(normalizeClaudeCommandName(command.Name), claudeCommandDiscoveryMaxNameBytes)
		if name == "" {
			continue
		}
		if _, exists := primary[name]; exists {
			continue
		}
		primary[name] = struct{}{}
		description := truncateClaudeCommandField(strings.TrimSpace(command.Description), claudeCommandDiscoveryMaxDescriptionBytes)
		hint := truncateClaudeCommandField(strings.TrimSpace(command.ArgumentHint), claudeCommandDiscoveryMaxHintBytes)
		out, catalogBytes = appendClaudeAvailableCommand(out, catalogBytes, name, description, hint)
	}
	seen := make(map[string]struct{}, len(primary))
	for name := range primary {
		seen[name] = struct{}{}
	}
	for _, command := range source {
		name := truncateClaudeCommandField(normalizeClaudeCommandName(command.Name), claudeCommandDiscoveryMaxNameBytes)
		if name == "" {
			continue
		}
		description := truncateClaudeCommandField(strings.TrimSpace(command.Description), claudeCommandDiscoveryMaxDescriptionBytes)
		hint := truncateClaudeCommandField(strings.TrimSpace(command.ArgumentHint), claudeCommandDiscoveryMaxHintBytes)
		for _, alias := range command.Aliases {
			alias = truncateClaudeCommandField(normalizeClaudeCommandName(alias), claudeCommandDiscoveryMaxNameBytes)
			if alias == "" {
				continue
			}
			if _, isPrimary := primary[alias]; isPrimary {
				continue
			}
			if _, exists := seen[alias]; exists {
				continue
			}
			aliasDescription := "Alias for /" + name
			if description != "" {
				aliasDescription += ": " + description
			}
			aliasDescription = truncateClaudeCommandField(aliasDescription, claudeCommandDiscoveryMaxDescriptionBytes)
			before := len(out)
			out, catalogBytes = appendClaudeAvailableCommand(out, catalogBytes, alias, aliasDescription, hint)
			if len(out) > before {
				seen[alias] = struct{}{}
			}
		}
	}
	if len(out) == 0 {
		return []commandbridge.AvailableCommand{}
	}
	return out
}

func appendClaudeAvailableCommand(out []commandbridge.AvailableCommand, catalogBytes int, name, description, hint string) ([]commandbridge.AvailableCommand, int) {
	if len(out) >= claudeCommandDiscoveryMaxCommands {
		return out, catalogBytes
	}
	command := commandbridge.AvailableCommand{Name: name, Description: description, InputHint: hint}
	size := claudeAvailableCommandWireSize(command)
	if size <= 0 || catalogBytes+size > claudeCommandDiscoveryMaxCatalogBytes {
		return out, catalogBytes
	}
	return append(out, command), catalogBytes + size
}

func claudeAvailableCommandWireSize(command commandbridge.AvailableCommand) int {
	item := map[string]any{
		"name":        strings.TrimSpace(command.Name),
		"description": strings.TrimSpace(command.Description),
	}
	if hint := strings.TrimSpace(command.InputHint); hint != "" {
		item["input"] = map[string]string{"hint": hint}
	}
	raw, err := json.Marshal(item)
	if err != nil {
		return 0
	}
	return len(raw) + 1 // a comma or closing-array byte in the enclosing list
}

func truncateClaudeCommandField(value string, maxBytes int) string {
	value = strings.TrimSpace(value)
	if maxBytes <= 0 || len(value) <= maxBytes {
		return value
	}
	limit := maxBytes
	for limit > 0 && !utf8.RuneStart(value[limit]) {
		limit--
	}
	return strings.TrimSpace(value[:limit])
}

func normalizeClaudeCommandName(name string) string {
	name = strings.TrimSpace(name)
	name = strings.TrimLeft(name, "/")
	if name == "" || strings.ContainsAny(name, "\x00\r\n\t ") {
		return ""
	}
	return name
}

type claudeCommandDiscoveryCountingReader struct {
	io.Reader
	BytesRead int64
}

func (r *claudeCommandDiscoveryCountingReader) Read(p []byte) (int, error) {
	n, err := r.Reader.Read(p)
	r.BytesRead += int64(n)
	return n, err
}

package claudecodeadapter

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"strconv"
	"strings"

	"github.com/hecatehq/acp-adapter-kit/commandbridge"
	adapterprocess "github.com/hecatehq/acp-adapter-kit/process"
)

func classifyClaudePromptFailure(session commandbridge.Session, command adapterprocess.Spec, result adapterprocess.Result, runErr error) commandbridge.PromptFailureKind {
	if runErr == nil || command.Command != "claude" || session.ID == "" || result.StdoutTruncated || result.StderrTruncated {
		return commandbridge.PromptFailureUnknown
	}
	var exitErr *adapterprocess.ExitError
	if !errors.As(runErr, &exitErr) {
		return commandbridge.PromptFailureUnknown
	}

	sessionID, ok := claudeResumeSessionID(command.Args)
	if !ok || sessionID != session.ID || !missingClaudeSessionError(result.Stderr, sessionID) || !missingClaudeSessionStdout(result.Stdout, sessionID) {
		return commandbridge.PromptFailureUnknown
	}
	return commandbridge.PromptFailureNativeSessionMissing
}

func missingClaudeSessionStdout(stdout []byte, sessionID string) bool {
	trimmed := bytes.TrimSpace(stdout)
	if len(trimmed) == 0 {
		return true
	}
	if bytes.Contains(trimmed, []byte{'\n'}) {
		return false
	}
	if !hasUniqueJSONKeys(trimmed) {
		return false
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(trimmed, &fields); err != nil ||
		!hasExactJSONFields(fields,
			"type", "subtype", "duration_ms", "duration_api_ms", "is_error", "num_turns", "stop_reason",
			"session_id", "total_cost_usd", "usage", "modelUsage", "permission_denials", "uuid", "errors") {
		return false
	}
	var usageFields map[string]json.RawMessage
	if err := json.Unmarshal(fields["usage"], &usageFields); err != nil ||
		!hasExactJSONFields(usageFields,
			"input_tokens", "cache_creation_input_tokens", "cache_read_input_tokens", "output_tokens",
			"server_tool_use", "service_tier", "cache_creation", "inference_geo", "iterations", "speed") {
		return false
	}
	var serverToolFields map[string]json.RawMessage
	if err := json.Unmarshal(usageFields["server_tool_use"], &serverToolFields); err != nil ||
		!hasExactJSONFields(serverToolFields, "web_search_requests", "web_fetch_requests") {
		return false
	}
	var cacheCreationFields map[string]json.RawMessage
	if err := json.Unmarshal(usageFields["cache_creation"], &cacheCreationFields); err != nil ||
		!hasExactJSONFields(cacheCreationFields, "ephemeral_1h_input_tokens", "ephemeral_5m_input_tokens") {
		return false
	}
	durationMS, durationOK := rawJSONInt64(fields["duration_ms"])
	typeName, typeOK := rawJSONString(fields["type"])
	subtype, subtypeOK := rawJSONString(fields["subtype"])
	resultSessionID, resultSessionOK := rawJSONString(fields["session_id"])
	resultUUID, resultUUIDOK := rawJSONString(fields["uuid"])
	serviceTier, serviceTierOK := rawJSONString(usageFields["service_tier"])
	_, inferenceGeoOK := rawJSONString(usageFields["inference_geo"])
	speed, speedOK := rawJSONString(usageFields["speed"])
	var reportedErrors []string
	errorsOK := rawJSONArray(fields["errors"], &reportedErrors)
	wantError := "No conversation found with session ID: " + sessionID
	return typeOK && typeName == "result" &&
		subtypeOK && subtype == "error_during_execution" &&
		durationOK && durationMS >= 0 &&
		rawJSONNumberIsZero(fields["duration_api_ms"]) &&
		bytes.Equal(bytes.TrimSpace(fields["is_error"]), []byte("true")) &&
		rawJSONNumberIsZero(fields["num_turns"]) &&
		bytes.Equal(bytes.TrimSpace(fields["stop_reason"]), []byte("null")) &&
		resultSessionOK && validClaudeSessionID(resultSessionID) &&
		rawJSONNumberIsZero(fields["total_cost_usd"]) &&
		rawJSONNumberIsZero(usageFields["input_tokens"]) &&
		rawJSONNumberIsZero(usageFields["cache_creation_input_tokens"]) &&
		rawJSONNumberIsZero(usageFields["cache_read_input_tokens"]) &&
		rawJSONNumberIsZero(usageFields["output_tokens"]) &&
		rawJSONNumberIsZero(serverToolFields["web_search_requests"]) &&
		rawJSONNumberIsZero(serverToolFields["web_fetch_requests"]) &&
		rawJSONNumberIsZero(cacheCreationFields["ephemeral_1h_input_tokens"]) &&
		rawJSONNumberIsZero(cacheCreationFields["ephemeral_5m_input_tokens"]) &&
		rawJSONArrayIsEmpty(usageFields["iterations"]) &&
		serviceTierOK && serviceTier != "" &&
		inferenceGeoOK &&
		speedOK && speed != "" &&
		rawJSONObjectIsEmpty(fields["modelUsage"]) &&
		rawJSONArrayIsEmpty(fields["permission_denials"]) &&
		resultUUIDOK && validClaudeSessionID(resultUUID) &&
		errorsOK && len(reportedErrors) == 1 &&
		reportedErrors[0] == wantError
}

func hasExactJSONFields(fields map[string]json.RawMessage, names ...string) bool {
	if len(fields) != len(names) {
		return false
	}
	for _, name := range names {
		if _, ok := fields[name]; !ok {
			return false
		}
	}
	return true
}

func hasUniqueJSONKeys(data []byte) bool {
	decoder := json.NewDecoder(bytes.NewReader(data))
	if !consumeUniqueJSONValue(decoder) {
		return false
	}
	var trailing any
	return errors.Is(decoder.Decode(&trailing), io.EOF)
}

func consumeUniqueJSONValue(decoder *json.Decoder) bool {
	token, err := decoder.Token()
	if err != nil {
		return false
	}
	delimiter, ok := token.(json.Delim)
	if !ok {
		return true
	}
	switch delimiter {
	case '{':
		seen := map[string]struct{}{}
		for decoder.More() {
			keyToken, err := decoder.Token()
			if err != nil {
				return false
			}
			key, ok := keyToken.(string)
			if !ok {
				return false
			}
			if _, duplicate := seen[key]; duplicate {
				return false
			}
			seen[key] = struct{}{}
			if !consumeUniqueJSONValue(decoder) {
				return false
			}
		}
		closing, err := decoder.Token()
		return err == nil && closing == json.Delim('}')
	case '[':
		for decoder.More() {
			if !consumeUniqueJSONValue(decoder) {
				return false
			}
		}
		closing, err := decoder.Token()
		return err == nil && closing == json.Delim(']')
	default:
		return false
	}
}

func rawJSONString(raw json.RawMessage) (string, bool) {
	if len(raw) == 0 || bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return "", false
	}
	var value string
	if err := json.Unmarshal(raw, &value); err != nil {
		return "", false
	}
	return value, true
}

func rawJSONInt64(raw json.RawMessage) (int64, bool) {
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.UseNumber()
	var value any
	if err := decoder.Decode(&value); err != nil {
		return 0, false
	}
	number, ok := value.(json.Number)
	if !ok || strings.ContainsAny(number.String(), ".eE") {
		return 0, false
	}
	parsed, err := strconv.ParseInt(number.String(), 10, 64)
	return parsed, err == nil
}

func rawJSONNumberIsZero(raw json.RawMessage) bool {
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.UseNumber()
	var value any
	if err := decoder.Decode(&value); err != nil {
		return false
	}
	number, ok := value.(json.Number)
	if !ok {
		return false
	}
	mantissa := strings.SplitN(strings.SplitN(number.String(), "e", 2)[0], "E", 2)[0]
	sawDigit := false
	for _, character := range mantissa {
		switch {
		case character == '0':
			sawDigit = true
		case character == '-' || character == '.':
		case character >= '1' && character <= '9':
			return false
		default:
			return false
		}
	}
	return sawDigit
}

func rawJSONArray(raw json.RawMessage, target any) bool {
	trimmed := bytes.TrimSpace(raw)
	return len(trimmed) > 0 && trimmed[0] == '[' && json.Unmarshal(trimmed, target) == nil
}

func rawJSONArrayIsEmpty(raw json.RawMessage) bool {
	var values []json.RawMessage
	return rawJSONArray(raw, &values) && len(values) == 0
}

func rawJSONObjectIsEmpty(raw json.RawMessage) bool {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || trimmed[0] != '{' {
		return false
	}
	var values map[string]json.RawMessage
	return json.Unmarshal(trimmed, &values) == nil && len(values) == 0
}

func claudeResumeSessionID(args []string) (string, bool) {
	// PromptCommand always appends the user prompt as the final argument. Keep
	// prompt text such as "--resume" or "--session-id" outside option parsing.
	optionEnd := len(args) - 1
	if optionEnd <= 0 {
		return "", false
	}
	resumeID := ""
	for index := 0; index < optionEnd; index++ {
		switch args[index] {
		case "--":
			return resumeID, resumeID != ""
		case "--resume":
			if resumeID != "" || index+1 >= optionEnd || !validClaudeSessionID(args[index+1]) {
				return "", false
			}
			resumeID = args[index+1]
			index++
		case "--session-id":
			return "", false
		}
	}
	return resumeID, resumeID != ""
}

func missingClaudeSessionError(stderr []byte, sessionID string) bool {
	want := "No conversation found with session ID: " + sessionID
	for _, line := range bytes.Split(stderr, []byte{'\n'}) {
		if strings.TrimSpace(string(line)) == want {
			return true
		}
	}
	return false
}

// Package claudecodeadapter exposes the Claude Code-specific ACP adapter
// wiring for hosts that want to embed the adapter as a library instead of
// launching the claude-code-acp-adapter binary.
package claudecodeadapter

import (
	"crypto/rand"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"regexp"
	"strings"

	"github.com/hecatehq/acp-adapter-kit/acp"
	"github.com/hecatehq/acp-adapter-kit/adaptercli"
	"github.com/hecatehq/acp-adapter-kit/commandbridge"
	"github.com/hecatehq/acp-adapter-kit/doctor"
	adapterprocess "github.com/hecatehq/acp-adapter-kit/process"
	"github.com/hecatehq/acp-adapter-kit/runtimeacp"
)

const (
	Name  = "claude-code-acp-adapter"
	Title = "Claude Code ACP Adapter"
)

const configDefault = "__default__"
const authMethodAgentLogin = "agent-login"

var claudeSessionIDPattern = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)

func NewCLISpec(version string, stdin io.Reader, stdout io.Writer, stderr io.Writer) adaptercli.Spec {
	return adaptercli.Spec{
		Info:   Info(version),
		Short:  "ACP adapter for Claude Code",
		Stdin:  stdin,
		Stdout: stdout,
		Stderr: stderr,
		Runtime: adaptercli.RuntimeSpec{
			InheritEnv: RuntimeEnv(),
		},
		Command: CommandSpec(),
		Doctor:  DoctorSpec(),
	}
}

func Info(version string) acp.AdapterInfo {
	return acp.AdapterInfo{
		Name:    Name,
		Title:   Title,
		Version: version,
		// Claude's non-interactive CLI consumes attachment paths in prompt text,
		// not ACP inline image/blob blocks. Keep those capabilities false so the
		// host supplies private resource links that the shared bridge can forward.
		Capabilities: acp.Capabilities{
			MCPHTTP:               true,
			MCPSSE:                true,
			LoadSession:           true,
			SessionList:           true,
			SessionResume:         true,
			SessionClose:          true,
			SessionDelete:         true,
			AdditionalDirectories: true,
		},
	}
}

func NewServer(version string) *acp.Server {
	return NewServerWithRunner(version, nil)
}

// NewServerWithRunner builds the embeddable ACP server with a host-owned
// provider process runner. A nil runner preserves the standalone adapter's
// fixed-argv process behavior. A runner that also implements
// commandbridge.CommandStarter lets live command discovery use the same bound
// Claude binary and environment as prompts.
func NewServerWithRunner(version string, runner commandbridge.Runner) *acp.Server {
	spec := CommandSpec()
	if runner != nil {
		spec.Runner = runner
	}
	return acp.NewServer(Info(version), commandbridge.New(*spec).Options()...)
}

func Options() []acp.Option {
	return commandbridge.New(*CommandSpec()).Options()
}

func CommandSpec() *commandbridge.Spec {
	return &commandbridge.Spec{
		NewID:                   newClaudeSessionID,
		LoadUnknownSessions:     true,
		Options:                 ConfigOptions(),
		DiscoverCommands:        discoverAvailableCommands,
		CommandDiscoveryTimeout: claudeCommandDiscoveryTimeout,
		AuthMethods:             AuthMethods(),
		IncludeTranscript:       true,
		BuildPrompt:             PromptCommand,
		BuildAuthenticate:       AuthenticateCommand,
		BuildLogout:             LogoutCommand,
		AuthRequired:            CommandAuthRequired,
		ClassifyPromptFailure:   classifyClaudePromptFailure,
		NewStreamParser:         NewStreamParser,
	}
}

func AuthMethods() []acp.AuthMethod {
	return []acp.AuthMethod{{
		ID:          authMethodAgentLogin,
		Name:        "Claude Code login",
		Description: "Sign in with the local Claude Code CLI.",
	}}
}

// AvailableCommands is retained for source compatibility with embedders that
// used the pre-v0.3 catalog helper. It intentionally returns no bootstrap
// commands: provider-owned available_commands_update snapshots from live
// discovery are now the authoritative command inventory.
//
// Deprecated: consume ACP available_commands_update notifications instead.
func AvailableCommands() []commandbridge.AvailableCommand {
	return nil
}

func ConfigOptions() []commandbridge.SelectConfigOption {
	return []commandbridge.SelectConfigOption{
		{
			ID:           "model",
			Name:         "Model",
			Description:  "Claude Code model override. Default uses the operator's Claude configuration.",
			Category:     "model",
			DefaultValue: configDefault,
			Options: []commandbridge.SelectValue{
				{Value: configDefault, Name: "Configured default"},
				{Value: "sonnet", Name: "Sonnet"},
				{Value: "opus", Name: "Opus"},
			},
		},
		{
			ID:           "effort",
			Name:         "Effort",
			Description:  "Claude Code effort override. Default uses the operator's Claude configuration.",
			Category:     "thought_level",
			DefaultValue: configDefault,
			Options: []commandbridge.SelectValue{
				{Value: configDefault, Name: "Configured default"},
				{Value: "low", Name: "Low"},
				{Value: "medium", Name: "Medium"},
				{Value: "high", Name: "High"},
				{Value: "xhigh", Name: "xHigh"},
				{Value: "max", Name: "Max"},
			},
		},
		{
			ID:           "permission_mode",
			Name:         "Permission mode",
			Description:  "Claude Code permission mode. Default matches the adapter's non-interactive dontAsk boundary.",
			Category:     "permission",
			DefaultValue: "dontAsk",
			Options: []commandbridge.SelectValue{
				{Value: "dontAsk", Name: "Do not ask"},
				{Value: "default", Name: "Default"},
				{Value: "acceptEdits", Name: "Accept edits"},
				{Value: "auto", Name: "Auto"},
